אַתָּה הוּא י~הוה אֱ~לֹהֵינוּ שֶׁהִקְטִירוּ אֲבוֹתֵינוּ לְפָנֶיךָ אֶת קְטֹרֶת הַסַּמִּים בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ הָיָה קַיָּם, כַּאֲשֶׁר צִוִּיתָ אוֹתָם עַל יַד מֹשֶׁה נְבִיאֶךָ, כַּכָּתוּב בְּתוֹרָתֶךָ:

וַיֹּאמֶר י~הוה אֶל מֹשֶׁה, קַח לְךָ סַמִּים נָטָף וּשְׁחֵלֶת וְחֶלְבְּנָה סַמִּים וּלְבֹנָה זַכָּה בַּד בְּבַד יִהְיֶה; וְעָשִׂיתָ אֹתָהּ קְטֹרֶת, רֹקַח מַעֲשֶׂה רוֹקֵחַ, מְמֻלָּח טָהוֹר קֹדֶשׁ; וְשָׁחַקְתָּ מִמֶּנָּה הָדֵק, וְנָתַתָּה מִמֶּנָּה לִפְנֵי הָעֵדֻת בְּאֹהֶל מוֹעֵד אֲשֶׁר אִוָּעֵד לְךָ שָׁמָּה, קֹדֶשׁ קָדָשִׁים תִּהְיֶה לָכֶם;
וְנֶאֱמַר: וְהִקְטִיר עָלָיו אַהֲרֹן קְטֹרֶת סַמִּים, בַּבֹּקֶר בַּבֹּקֶר בְּהֵיטִיבוֹ אֶת הַנֵּרוֹת יַקְטִירֶנָּה; וּבְהַעֲלֹת אַהֲרֹן אֶת הַנֵּרֹת בֵּין הָעַרְבַּיִם יַקְטִירֶנָּה, קְטֹרֶת תָּמִיד לִפְנֵי י~הוה לְדֹרֹתֵיכֶם;

תָּנוּ רַבָּנָן: פִּטּוּם הַקְּטֹרֶת כֵּיצַד? שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וּשְׁמוֹנָה מָנִים הָיוּ בָהּ. שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וַחֲמִשָּׁה כְּמִנְיַן יְמוֹת הַחַמָּה, מָנֶה לְכָל יוֹם, פְּרַס בְּשַׁחֲרִית וּפְרַס בֵּין הָעַרְבָּיִם. וּשְׁלֹשָׁה מָנִים יְתֵרִים שֶׁמֵּהֶם מַכְנִיס כֹּהֵן גָּדוֹל מְלֹא חָפְנָיו בְּיוֹם הַכִּפּוּרִים, וּמַחֲזִירָן לְמַכְתֶּשֶׁת בְּעֶרֶב יום הַכִּפּוּרִים, וְשׁוֹחֲקָן יָפֶה יָפֶה כְּדֵי לְקַיֵּם מִצְוַת דַקָּה מִן הַדַּקָּה.

וְאַחַד עָשר סַמְמָנִים הָיוּ בָהּ, וְאֵלּוּ הֵן: (א) הַצֳּרִי (ב) וְהַצִּפֹּרֶן, (ג) וְהַחֶלְבְּנָה (ד) וְהַלְּבוֹנָה מִשְׁקַל שִׁבְעִים שִׁבְעִים מָנֶה, (ה) מֹר (ו) וּקְצִיעָה, (ז) שִׁבֹּלֶת נֵרְדְּ (ח) וְכַרְכֹּם מִשְׁקַל שִׁשָּׁה עָשָׂר שִׁשָּׁה עָשָׂר מָנֶה, (ט) הַקֹּסְטְ שְׁנֵים עָשָׂר, (י) וְקִלּוּפָה שְׁלֹשָׁה, (יא) וְקִנָּמון תִּשְׁעָה, בֹּרִית כַּרְשִׁינָה תִּשְׁעָה קַבִּין, יֵין קַפְרִיסִין סְאִין תְּלָתָא וְקַבִּין תְּלָתָא, וְאִם לוׂ אֵין יֵין קַפְרִיסִין מֵבִיא חֲמַר חִוַּרְיָן עַתִּיק. מֶלַח סְדוֹמִית רֹבַע מַעֲלֶה עָשָׁן כָּל שֶׁהוּא. רַבִּי נָתָן הַבַּבְלִי אוֹמֵר: אַף כִּפַּת הַיַּרְדֵּן כָּל שֶׁהוּא. וְאִם נָתַן בָּהּ דְּבַשׁ פְּסָלָהּ, וְאִם חִסַּר אַחַת מִכָּל סַמָּנֶיהָ חַיָּב.

רַבָּן שִׁמְעוֹן בֶּן גַּמְלִיאֵל אוֹמֵר: הַצֳּרִי אֵינוֹ אֶלָּא שְׂרָף הַנּוֹטֵף מֵעֲצֵי הַקְּטָף. בֹּרִית כַּרְשִׁינָה לָמָה הִיא בָאָה כְדֵי לְיַפוֹת בָּה אֶת הַצִּפֹּרֶן כְּדֵי שֶׁתְּהֵא נָאֶה. יֵין קַפְרִיסִין שֶׁשׁוֹרִין בּוֹ אֶת הַצִּפֹּרֶן כְּדֵי שֶׁתְּהֵא עַזָּה. וַהֲלֹא מֵי רַגְלַיִם יָפִין לָהּ, אֶלָּא שֶׁאֵין מַכְנִיסִין מֵי רַגְלַיִם בַּעֲזָרָה מִפְּנֵי הַכָּבוֹד.

תַּנְיָא: רַבִּי נָתָן אוֹמֵר: כְּשֶׁהוּא שׁוֹחֵק אוֹמֵר: הָדֵק הֵיטֵב, הֵיטֵב הָדֵק, מִפְּנֵי שֶׁהַקּוֹל יָפֶה לַבְּשָׂמִים.

י~הוה צְ~בָאוֹת עִמָּנוּ, מִשְׂגָּב לָנוּ אֱ~לֹהֵי יַעֲקֹב סֶלָה;
י~הוה צְ~בָאוֹת עִמָּנוּ, מִשְׂגָּב לָנוּ אֱ~לֹהֵי יַעֲקֹב סֶלָה;
י~הוה צְ~בָאוֹת עִמָּנוּ, מִשְׂגָּב לָנוּ אֱ~לֹהֵי יַעֲקֹב סֶלָה;

י~הוה צְ~בָאוֹת, אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ;
י~הוה צְ~בָאוֹת, אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ;
י~הוה צְ~בָאוֹת, אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ;

י~הוה הוֹשִׁיעָה, הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ;
י~הוה הוֹשִׁיעָה, הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ;
י~הוה הוֹשִׁיעָה, הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ;

אַתָּה סֵתֶר לִי מִצַּר תִּצְּרֵנִי רָנֵּי פַלֵּט תְּסוֹבְבֵנִי סֶלָה; 
וְעָרְבָה לַי~הוה מִנְחַת יְהוּדָה וִירוּשָׁלָיִם כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיּות;

אָנָּא בְּכֹחַ גְּדֻלַּת יְמִינְךָ, תַּתִּיר צְרוּרָה (אב"ג ית"ץ).
קַבֵּל רִנַּת עַמְּךָ, שַׂגְּבֵנוּ, טַהֲרֵנוּ, נוֹרָא (קר"ע שט"ן).
נָא גִּבּוֹר, דּוֹרְשֵׁי יִחוּדֶךָ, כְּבָבַת שָׁמְרֵם (נג"ד יכ"ש).
בָּרְכֵם, טַהֲרֵם, רַחֲמֵם, צִדְקָתְךָ תָּמִיד גָּמְלֵם (בט"ר צת"ג).
חָסִין קָדוֹשׁ, בְּרֹב טוּבְךָ נַהֵל עֲדָתֶךָ (חק"ב טנ"ע).
יָחִיד גֵּאֶה, לְעַמְּךָ פְנֵה, זוֹכְרֵי קְדֻשָּׁתֶךָ (יג"ל פז"ק).
שַׁוְעָתֵנוּ קַבֵּל, וּשְׁמַע צַעֲקָתֵנוּ, יוֹדֵעַ תַּעֲלוּמוֹת (שק"ו צי"ת).
בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֵד.



אַשְׁרֵי יוֹשְׁבֵי בֵיתֶךָ עוֹד יְהַלְלוּךָ סֶּלָה;
אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁי~הוה אֱ~לֹהָיו;
תְּהִלָּה לְדָוִד, אֲרוֹמִמְךָ אֱ~לוֹהַי הַמֶּלֶךְ וַאֲבָרְכָה שִׁמְךָ לְעוֹלָם וָעֶד;
בְּכָל יוֹם אֲבָרְכֶךָּ וַאֲהַלְלָה שִׁמְךָ לְעוֹלָם וָעֶד;
גָּדוֹל י~הוה וּמְהֻלָּל מְאֹד וְלִגְדֻלָּתוֹ אֵין חֵקֶר;
דּוֹר לְדוֹר יְשַׁבַּח מַעֲשֶׂיךָ וּגְבוּרֹתֶיךָ יַגִּידוּ;
הֲדַר כְּבוֹד הוֹדֶךָ וְדִבְרֵי נִפְלְאוֹתֶיךָ אָשִׂיחָה;
וֶעֱזוּז נוֹרְאֹתֶיךָ יֹאמֵרוּ וּגְדוּלָּתְךָ אֲסַפְּרֶנָּה;
זֵכֶר רַב טוּבְךָ יַבִּיעוּ וְצִדְקָתְךָ יְרַנֵּנוּ;
חַנּוּן וְרַחוּם י~הוה אֶרֶךְ אַפַּיִם וּגְדָל חָסֶד;
טוֹב י~הוה לַכֹּל וְרַחֲמָיו עַל כָּל מַעֲשָׂיו;
יוֹדוּךָ י~הוה כָּל מַעֲשֶׂיךָ וַחֲסִידֶיךָ יְבָרְכוּכָה;
כְּבוֹד מַלְכוּתְךָ יֹאמֵרוּ וּגְבוּרָתְךָ יְדַבֵּרוּ;
לְהוֹדִיעַ לִבְנֵי הָאָדָם גְּבוּרֹתָיו וּכְבוֹד הֲדַר מַלְכוּתוֹ;
מַלְכוּתְךָ מַלְכוּת כָּל עֹלָמִים וּמֶמְשֶׁלְתְּךָ בְּכָל דּוֹר וָדוֹר;
סוֹמֵךְ י~הוה לְכָל הַנֹּפְלִים וְזוֹקֵף לְכָל הַכְּפוּפִים;
עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ וְאַתָּה נוֹתֵן לָהֶם אֶת אָכְלָם בְּעִתּוֹ;
פּוֹתֵחַ אֶת יָדֶךָ וּמַשְׂבִּיעַ לְכָל חַי רָצוֹן;
צַדִּיק י~הוה בְּכָל דְּרָכָיו וְחָסִיד בְּכָל מַעֲשָׂיו;
קָרוֹב י~הוה לְכָל קֹרְאָיו לְכֹל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת;
רְצוֹן יְרֵאָיו יַעֲשֶׂה וְאֶת שַׁוְעָתָם יִשְׁמַע וְיוֹשִׁיעֵם;
שׁוֹמֵר י~הוה אֶת כָּל אֹהֲבָיו וְאֵת כָּל הָרְשָׁעִים יַשְׁמִיד;
תְּהִלַּת י~הוה יְדַבֶּר פִּי וִיבָרֵךְ כָּל בָּשָׂר שֵׁם קָדְשׁוֹ לְעוֹלָם וָעֶד;
וַאֲנַחְנוּ נְבָרֵךְ יָ~הּ מֵעַתָּה וְעַד עוֹלָם הַלְלוּיָ~הּ;


